            className="flex flex-wrap items-center gap-1"
          >
            {visible.map((r, i) => (
              <button
                data-brand-control-id="control:selection"
                key={r.id}
                ref={(el) => {
                  buttonRefs.current[i] = el;
                }}
                type="button"
                data-status={releaseWeightState(r)}
                data-provenance={r.provenance}
                aria-label={r.name}
                aria-pressed={r.id === selected.id}
                onClick={() => select(i)}
