            <span className="ml-1 font-sans text-[13px] text-text-dim">
              {`${visible.length} of ${GENERALIST_RELEASES.length} shown`}
            </span>
          </div>
          <div>
            <InstrumentReset onClick={reset} />
          </div>
        </>
      }
      stage={
        <FigureStage
          footer={
            <div
              data-testid="release-detail"
              aria-live="polite"
              className="basis-full font-sans text-[13px]"
