              <thead>
                <tr className="border-b border-border-strong">
                  <th scope="col" className={TABLE_HEADER_CELL}>Hand</th>
                  <th
                    scope="col"
                    aria-sort={sort.key === 'dof' ? (sort.direction === 'asc' ? 'ascending' : 'descending') : undefined}
                    className={TABLE_HEADER_CELL}
                  >
