                    </th>
                    <td className={cx(TABLE_CELL, 'whitespace-nowrap tabular-nums')}>{hand.dofDisplay}</td>
                    <td className={cx(TABLE_CELL, 'whitespace-nowrap tabular-nums')}>
                      {hand.tactileDisplay ? (
                        <>
                          {hand.tactileDisplay}
