    const preset = PER_STEP_PRESETS.find((p) => p.id === id)!;
    setPerStepPercent(preset.percent);
    const linked = presetSet?.find((p) => Math.abs(p.perStep * 100 - preset.percent) < 0.05);
    if (linked) setSteps(linked.steps);
