  const { path, marker, sampleRows } = useMemo(() => {
    const curve = compoundingCurve(perStep, maxSteps);
    const d = curve
      .map((p, n) => `${n === 0 ? 'M' : 'L'}${scaleX(n, maxSteps).toFixed(2)},${scaleY(p).toFixed(2)}`)
