    // from, so the two can never disagree (VAL-EDU-023) and the sample
    // moves with the per-step control (VAL-EDU-024).
    const sample = [0, 10, 25, 50, 75, maxSteps].map((n) => ({
      label: `${n} step${n === 1 ? '' : 's'}`,
      values: [
        `${(compoundedSuccessRate(perStep, n) * 100).toFixed(1)}%`,
      ],
    }));
