/** Runs of consecutive kept cells, so a lost reading leaves a gap in the guess. */
function keptRuns(occluded: readonly boolean[]): number[][] {
  const runs: number[][] = [];
  let run: number[] = [];
  occluded.forEach((lost, i) => {
    if (lost) {
      if (run.length) runs.push(run);
      run = [];
    } else {
      run.push(i);
    }
  });
  if (run.length) runs.push(run);
  return runs;
}

